private const val GUIA_BASE = "https://www.guiadosquadrinhos.com"

private fun resolveGuiaUrl(pathOrUrl: String): String {
    val raw = pathOrUrl.trim()
    if (raw.startsWith("http://www.guiadosquadrinhos.com", ignoreCase = true)) {
        return raw.replaceFirst("http://", "https://")
    }
    if (raw.startsWith("https://") || raw.startsWith("http://")) return raw
    return "$GUIA_BASE/${raw.removePrefix("/")}"
}

/**
 * Tela de detalhe de uma edição.
 *
 * O card "Pertence ao título X" é exibido automaticamente quando a edição
 * contém o link "Galeria de capas" no HTML (details.seriesUrl != null).
 * Edições sem esse link são salvas automaticamente com isStandalone = true.
 */
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun DetailsScreen(
    navController: NavController,
    encodedEditionUrl: String,
    encodedEditionTitle: String,
    onBackClick: () -> Unit,
    showSeriesCard: Boolean = true,
    encodedSeriesUrl: String? = null,
    encodedSeriesTitle: String? = null,
    galleryViewModel: GalleryViewModel = hiltViewModel(),
    viewModel: EditionViewModel = hiltViewModel()
) {
    val editionUrl = navDecode(encodedEditionUrl)
    val editionTitle = navDecode(encodedEditionTitle)
    val state by viewModel.state.collectAsState()
    val galleryMap by galleryViewModel.galleryMap.collectAsState()
    val uriHandler = LocalUriHandler.current

    LaunchedEffect(editionUrl) { viewModel.load(editionUrl) }

    Scaffold(
        topBar = {
            TopAppBar(
                title = {
                    SiegeText(
                        text = editionTitle,
                        style = SiegeTextStyle.Body,
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis
                    )
                },
                navigationIcon = {
                    IconButton(onClick = onBackClick) {
                        SiegeIcon(
                            icon = SiegeIcons.ic_arrow_solid,
                            contentDescription = "Voltar",
                            tint = SiegeTheme.colors.textPrimary
                        )
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(
                    containerColor = SiegeTheme.colors.surface,
                    titleContentColor = SiegeTheme.colors.textPrimary
                )
            )
        }
    ) { innerPadding ->
        when (val s = state) {
            is UiState.Idle, is UiState.Loading -> Box(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(innerPadding),
                contentAlignment = Alignment.Center
            ) { CircularProgressIndicator(color = SiegeColors.AccentPink) }

            is UiState.Error -> Column(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(innerPadding)
                    .padding(SiegeSpacing.Regular),
                horizontalAlignment = Alignment.CenterHorizontally,
                verticalArrangement = Arrangement.Center
            ) {
                SiegeText(
                    text = s.message,
                    style = SiegeTextStyle.Body,
                    color = SiegeColors.Error,
                    textAlign = TextAlign.Center
                )
                Spacer(Modifier.height(SiegeSpacing.Medium))
                SiegeButton(
                    text = "Tentar novamente",
                    style = SiegeButtonStyle.Primary,
                    onClick = { viewModel.load(editionUrl) })
            }

            is UiState.Empty -> Box(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(innerPadding),
                contentAlignment = Alignment.Center
            ) {
                SiegeText(
                    text = "Dados não encontrados",
                    style = SiegeTextStyle.Body,
                    color = SiegeTheme.colors.textTertiary
                )
            }

            is UiState.Success, is UiState.LoadingMore -> {
                val details = when (s) {
                    is UiState.Success -> s.data
                    is UiState.LoadingMore -> s.currentData
                    else -> return@Scaffold
                }

                // isStandalone is determined by the scraped HTML:
                // details.seriesUrl is parsed from "div.boxnumeros a[href*='capas/']".
                // When that link is absent the edition has no parent series → standalone.
                val isStandalone = details.seriesUrl == null

                val resolvedSeriesUrl = if (showSeriesCard) details.seriesUrl else null
                val resolvedSeriesTitle = if (showSeriesCard && details.seriesUrl != null)
                    details.seriesTitle ?: encodedSeriesTitle?.let { navDecode(it) }
                else null

                val currentStatus = galleryMap[editionUrl]
                val currentItem = galleryViewModel.editionsFull.collectAsState().value[editionUrl]

                EditionContent(
                    details = details,
                    seriesTitle = resolvedSeriesTitle,
                    itemStatus = currentStatus,
                    isStandalone = isStandalone,
                    onSeriesClick = if (resolvedSeriesUrl != null && resolvedSeriesTitle != null) {
                        {
                            navController.navigate(
                                AppRoute.SeriesCovers.createRoute(
                                    navEncode(resolvedSeriesUrl),
                                    navEncode(resolvedSeriesTitle)
                                )
                            )
                        }
                    } else null,
                    onSaveItem = { status ->
                        galleryViewModel.saveItem(
                            UserItem(
                                guiaUrl = editionUrl,
                                title = details.title,
                                coverUrl = details.coverUrl,
                                seriesUrl = resolvedSeriesUrl,
                                seriesTitle = resolvedSeriesTitle,
                                ownership = status.ownership,
                                readStatus = status.readStatus,
                                isStandalone = isStandalone
                            )
                        )
                    },
                    onUpdateStatus = { status ->
                        if (status.isNotEmpty()) {
                            galleryViewModel.saveItem(
                                UserItem(
                                    id = currentItem?.id ?: "",
                                    guiaUrl = editionUrl,
                                    title = details.title,
                                    coverUrl = details.coverUrl,
                                    seriesUrl = resolvedSeriesUrl,
                                    seriesTitle = resolvedSeriesTitle,
                                    ownership = status.ownership,
                                    readStatus = status.readStatus,
                                    isStandalone = isStandalone
                                )
                            )
                        } else {
                            galleryViewModel.removeItem(editionUrl)
                        }
                    },
                    onRemoveItem = { galleryViewModel.removeItem(editionUrl) },
                    onOpenWeb = {
                        val fullUrl = resolveGuiaUrl(editionUrl)
                        uriHandler.openUri(fullUrl)
                    },
                    modifier = Modifier.padding(innerPadding)
                )
            }
        }
    }
}

// ── Conteúdo ──────────────────────────────────────────────────────────────────

@Composable
private fun EditionContent(
    details: ComicDetails,
    seriesTitle: String?,
    itemStatus: ItemStatus?,
    isStandalone: Boolean,
    onSeriesClick: (() -> Unit)?,
    onSaveItem: (ItemStatus) -> Unit,
    onUpdateStatus: (ItemStatus) -> Unit,
    onRemoveItem: () -> Unit,
    onOpenWeb: () -> Unit,
    modifier: Modifier = Modifier
) {
    LazyColumn(
        modifier = modifier.fillMaxSize(),
        verticalArrangement = Arrangement.spacedBy(SiegeSpacing.None)
    ) {
        // ── Card "Pertence ao título" — hidden for standalone editions ────────
        if (!isStandalone && seriesTitle != null && onSeriesClick != null) {
            item {
                SeriesBelongsToCard(
                    seriesTitle = seriesTitle,
                    onClick = onSeriesClick,
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = SiegeSpacing.Regular, vertical = SiegeSpacing.Regular)
                )
            }
        }

        // ── Capa ──────────────────────────────────────────────────────────────
        item {
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(vertical = SiegeSpacing.Large),
                contentAlignment = Alignment.Center
            ) {
                AsyncImage(
                    model = ImageRequest.Builder(LocalContext.current).data(details.coverUrl)
                        .crossfade(true).build(),
                    contentDescription = details.title,
                    contentScale = ContentScale.Fit,
                    modifier = Modifier
                        .width(200.dp)
                        .aspectRatio(2f / 3f)
                        .clip(SiegeShapes.Medium)
                        .background(SiegeTheme.colors.surfaceElevated)
                )
            }
        }

        // ── Título + data ─────────────────────────────────────────────────────
        item {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = SiegeSpacing.Regular),
                verticalArrangement = Arrangement.spacedBy(SiegeSpacing.XSmall)
            ) {
                SiegeText(text = details.title, style = SiegeTextStyle.Headline)
                details.publishedIn?.let {
                    SiegeText(
                        text = it,
                        style = SiegeTextStyle.Label,
                        color = SiegeTheme.colors.textTertiary
                    )
                }
            }
        }

        item { Spacer(Modifier.height(SiegeSpacing.Large)) }

        // ── Ficha técnica ─────────────────────────────────────────────────────
        item {
            InfoCard(
                title = "FICHA TÉCNICA",
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = SiegeSpacing.Regular)
            ) {
                listOfNotNull(
                    details.publisher?.let { "Editora" to it },
                    details.licensor?.let { "Licenciador" to it },
                    details.category?.let { "Categoria" to it },
                    details.genre?.let { "Gênero" to it },
                    details.status?.let { "Status" to it },
                    details.pages?.let { "Páginas" to it },
                    details.format?.let { "Formato" to it.replace("\n", " · ") },
                    details.coverPrice?.let { "Preço de capa" to it },
                    details.coverArtist?.let { "Arte da capa" to it }
                ).forEach { (label, value) -> InfoRow(label = label, value = value) }
            }
        }

        // ── Painel de galeria — edição ────────────────────────────────────────
        item { Spacer(Modifier.height(SiegeSpacing.Regular)) }
        item {
            GalleryPanel(
                itemStatus = itemStatus,
                onSaveItem = onSaveItem,
                onUpdateStatus = onUpdateStatus,
                onRemoveItem = onRemoveItem,
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = SiegeSpacing.Regular)
            )
        }

        // ── Botão ─────────────────────────────────────────────────────────────
        item { Spacer(Modifier.height(SiegeSpacing.Regular)) }
        item {
            SiegeButton(
                text = "Ver no Guia dos Quadrinhos",
                style = SiegeButtonStyle.Outlined,
                onClick = onOpenWeb,
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = SiegeSpacing.Regular)
            )
        }
        item { Spacer(Modifier.height(SiegeSpacing.XXLarge)) }
    }
}

// ── Painel de galeria ─────────────────────────────────────────────────────────

/**
 * Painel que permite ao usuário definir seu status para uma edição.
 *
 * Possui dois grupos independentes de chips:
 * - **POSSE**: Tenho / Quero (mutuamente exclusivos)
 * - **LEITURA**: Lido / Lendo (mutuamente exclusivos)
 *
 * Dentro de cada grupo, clicar no chip ativo o deseleciona (toggle).
 * isStandalone é definido automaticamente pela presença do link "Galeria de capas"
 * no HTML — não há switch de controle manual.
 */
@Composable
private fun GalleryPanel(
    itemStatus: ItemStatus?,
    onSaveItem: (ItemStatus) -> Unit,
    onUpdateStatus: (ItemStatus) -> Unit,
    onRemoveItem: () -> Unit,
    modifier: Modifier = Modifier
) {
    val currentOwnership = itemStatus?.ownership
    val currentReadStatus = itemStatus?.readStatus

    fun applyStatus(newOwnership: Ownership?, newRead: ReadStatus?) {
        val newStatus = ItemStatus(newOwnership, newRead)
        when {
            itemStatus == null -> if (newStatus.isNotEmpty()) onSaveItem(newStatus)
            newStatus.isNotEmpty() -> onUpdateStatus(newStatus)
            else -> onRemoveItem()
        }
    }

    SiegeCard(
        style = SiegeCardStyle.Filled,
        title = "MINHA GALERIA",
        titleColor = SiegeColors.AccentPink,
        modifier = modifier
    ) {

        // ── Grupo POSSE ───────────────────────────────────────────────────
        SiegeText(
            text = "POSSE",
            style = SiegeTextStyle.Label,
            color = SiegeTheme.colors.textTertiary
        )
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.spacedBy(SiegeSpacing.XSmall)
        ) {
            Ownership.entries.forEach { own ->
                val isSelected = own == currentOwnership
                val statusColor = own.badgeColor
                SiegeButton(
                    text = own.displayLabel,
                    style = if (isSelected)
                        ButtonStyle(
                            containerColor = statusColor,
                            contentColor = Color.Black,
                            borderColor = null
                        )
                    else
                        ButtonStyle(
                            containerColor = Color.Transparent,
                            contentColor = Color.Unspecified,
                            borderColor = statusColor
                        ),
                    iconRes = own.iconFor(isSelected),
                    onClick = { applyStatus(if (isSelected) null else own, currentReadStatus) },
                    modifier = Modifier.weight(1f)
                )
            }
        }

        // ── Grupo LEITURA ─────────────────────────────────────────────────
        Spacer(Modifier.height(SiegeSpacing.XXSmall))
        SiegeText(
            text = "LEITURA",
            style = SiegeTextStyle.Label,
            color = SiegeTheme.colors.textTertiary
        )
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.spacedBy(SiegeSpacing.XSmall)
        ) {
            ReadStatus.entries.forEach { read ->
                val isSelected = read == currentReadStatus
                val statusColor = read.badgeColor
                SiegeButton(
                    text = read.displayLabel,
                    style = if (isSelected)
                        ButtonStyle(
                            containerColor = statusColor,
                            contentColor = if (statusColor == SiegeColors.AccentPink) Color.White else Color.Black,
                            borderColor = null
                        )
                    else
                        ButtonStyle(
                            containerColor = Color.Transparent,
                            contentColor = Color.Unspecified,
                            borderColor = statusColor
                        ),
                    iconRes = read.iconFor(isSelected),
                    onClick = { applyStatus(currentOwnership, if (isSelected) null else read) },
                    modifier = Modifier.weight(1f)
                )
            }
        }

        // Botão remover — só visível quando já está na galeria
        if (itemStatus != null) {
            Spacer(Modifier.height(SiegeSpacing.XXSmall))
            SiegeButton(
                text = "Remover da galeria",
                style = SiegeButtonStyle.Ghost,
                onClick = onRemoveItem,
                modifier = Modifier.fillMaxWidth()
            )
        }
    }
}

// ── Card "Pertence ao título" ─────────────────────────────────────────────────

@Composable
private fun SeriesBelongsToCard(
    seriesTitle: String,
    onClick: () -> Unit,
    modifier: Modifier = Modifier
) {
    SiegeCard(style = SiegeCardStyle.Outlined, onClick = onClick, modifier = modifier) {
        Row(
            modifier = Modifier.fillMaxWidth(),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.SpaceBetween
        ) {
            Column(modifier = Modifier.weight(1f)) {
                SiegeText(
                    text = "Pertence ao título",
                    style = SiegeTextStyle.Label,
                    color = SiegeTheme.colors.textTertiary
                )
                SiegeText(
                    text = seriesTitle,
                    style = SiegeTextStyle.Body,
                    color = SiegeColors.AccentCyan,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis
                )
            }
            SiegeIcon(
                icon = SiegeIcons.ic_arrow_alt_solid,
                contentDescription = null,
                tint = SiegeTheme.colors.textTertiary,
                modifier = Modifier
                    .size(20.dp)
                    .graphicsLayer(scaleX = -1f)
            )
        }
    }
}

// ── Ficha técnica ─────────────────────────────────────────────────────────────

@Composable
private fun InfoCard(
    title: String,
    modifier: Modifier = Modifier,
    content: @Composable () -> Unit
) {
    SiegeCard(
        style = SiegeCardStyle.Filled,
        title = title,
        modifier = modifier
    ) {
        content()
    }
}

@Composable
private fun InfoRow(label: String, value: String) {
    Row(
        modifier = Modifier.fillMaxWidth(),
        horizontalArrangement = Arrangement.SpaceBetween,
        verticalAlignment = Alignment.Top
    ) {
        SiegeText(
            text = label,
            style = SiegeTextStyle.Label,
            color = SiegeTheme.colors.textTertiary,
            modifier = Modifier.weight(0.4f)
        )
        SiegeText(
            text = value,
            style = SiegeTextStyle.Label,
            color = SiegeTheme.colors.textPrimary,
            modifier = Modifier
                .weight(0.6f)
                .padding(start = SiegeSpacing.Small)
        )
    }
}

