-- Normaliza URLs legadas do Guia dos Quadrinhos para HTTPS -- Mantem URLs de outros dominios inalteradas.
-- 1) Capas salvas UPDATE user_editions SET cover_url = regexp_replace( cover_url, '^http://(www\.)?guiadosquadrinhos\.com', 'https://www.guiadosquadrinhos.com', 'i' ) WHERE cover_url ~* '^http://(www\.)?guiadosquadrinhos\.com';
UPDATE user_series SET cover_url = regexp_replace( cover_url, '^http://(www\.)?guiadosquadrinhos\.com', 'https://www.guiadosquadrinhos.com', 'i' ) WHERE cover_url ~* '^http://(www\.)?guiadosquadrinhos\.com';
-- 2) Links absolutos (quando existirem) em series/edicoes UPDATE user_editions SET guia_url = regexp_replace( guia_url, '^http://(www\.)?guiadosquadrinhos\.com', 'https://www.guiadosquadrinhos.com', 'i' ) WHERE guia_url ~* '^http://(www\.)?guiadosquadrinhos\.com';
UPDATE user_editions SET series_url = regexp_replace( series_url, '^http://(www\.)?guiadosquadrinhos\.com', 'https://www.guiadosquadrinhos.com', 'i' ) WHERE series_url ~* '^http://(www\.)?guiadosquadrinhos\.com';
UPDATE user_series SET series_url = regexp_replace( series_url, '^http://(www\.)?guiadosquadrinhos\.com', 'https://www.guiadosquadrinhos.com', 'i' ) WHERE series_url ~* '^http://(www\.)?guiadosquadrinhos\.com';
